def sine16_samples(n=3000):
    """The exact left/right samples that were encoded into SINE16_FRAMES."""
    seed, left, right = 12345, [], []
    for i in range(n):
        seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
        noise = (seed >> 16 & 0x7FF) - 1024
        left.append(int(9000 * math.sin(2 * math.pi * 330 * i / 48000) + 4000 * math.sin(2 * math.pi * 1250 * i / 48000)) + noise)
        right.append(int(7000 * math.sin(2 * math.pi * 440 * i / 48000 + 1)) - noise // 2)
    return left, right
